#include <bits/stdc++.h>
using namespace std;

vector<int> primes;

void sieve(int n) {
    vector<bool> isPrime(n + 1, true);
    isPrime[0] = isPrime[1] = false;

    for (int i = 2; i <= n / i; ++i) {
        if (isPrime[i]) {
            for (int j = i * i; j <= n; j += i) {
                isPrime[j] = false;
            }
        }
    }

    for (int i = 2; i <= n; ++i) {
        if (isPrime[i]) primes.push_back(i);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    sieve(1000000);

    int n;
    cin >> n;

    cout << lower_bound(primes.begin(), primes.end(), n) - primes.begin() << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

vector<int> v;
bitset<1000001> bs;

void criba(int N) {
    bs.set();
    bs[0] = bs[1] = 0;

    for (int i = 2; i <= N; ++i) {
        if (bs[i]) {
            v.push_back(i);
            if (1LL * i * i <= N) {
                for (long long j = 1LL * i * i; j <= N; j += i)
                    bs[j] = 0;
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    criba(1000000);

    int n;
    cin >> n;

    int sw = lower_bound(v.begin(), v.end(), n) - v.begin();
    cout << sw << '\n';

    return 0;
}

